public static double averageSalary(int[] rates, int[] hours) {
    int sum = 0;
    int i = 0;
    while (rates[i] >= 0) {
        sum = sum + rates[i] * hours[i];
        i++;
    }
    return (double) sum / i;   // i — מספר העובדים
}

public static int countAbove10000(int[] rates, int[] hours) {
    int count = 0;
    int i = 0;
    while (rates[i] >= 0) {
        if (rates[i] * hours[i] > 10000) {
            count++;
        }
        i++;
    }
    return count;
}

