public static String check(Object got, Object expected) {
    String g = String.valueOf(got).trim();
    String e = String.valueOf(expected);
    if (g.equals(e)) {
        return "נכון";
    }
    return "לא נכון — התקבל " + g + ", צריך להתקבל " + e;
}

exercise.mainCode:
System.out.println("סעיף א, בדיקה 1 (הדוגמה): " + check(averageSalary(new int[] { 50, 80, 45, 120, -1 }, new int[] { 160, 150, 180, 90, 0 }), 9725.0));
System.out.println("סעיף א, בדיקה 2 (עובד אחד): " + check(averageSalary(new int[] { 60, -1 }, new int[] { 100, 0 }), 6000.0));
System.out.println("סעיף א, בדיקה 3 (ממוצע לא שלם): " + check(averageSalary(new int[] { 30, 31, -5 }, new int[] { 100, 101, 0 }), 3065.5));
System.out.println("סעיף ב, בדיקה 1 (הדוגמה): " + check(countAbove10000(new int[] { 50, 80, 45, 120, -1 }, new int[] { 160, 150, 180, 90, 0 }), 2));
System.out.println("סעיף ב, בדיקה 2 (10000 בדיוק לא נספר): " + check(countAbove10000(new int[] { 100, 101, -1 }, new int[] { 100, 100, 0 }), 1));
System.out.println("סעיף ב, בדיקה 3 (אין עובדים): " + check(countAbove10000(new int[] { -1 }, new int[] { 0 }), 0));

